Q: How to use over scroll mode in Android A: <p>Change your RelativeLayout so that the <code>android:layout_height="wrap_content"</code>
Also do your own custom scrollview so that it intercepts the movement and nothing else:  </p>

<pre><code>public class VerticalScrollView extends ScrollView {
private float xDistance, yDistance, lastX, lastY;

public VerticalScrollView(Context context, AttributeSet attrs) {
    super(context, attrs);
}

@Override
public boolean onInterceptTouchEvent(MotionEvent ev) {
    switch (ev.getAction()) {
        case MotionEvent.ACTION_DOWN:
            xDistance = yDistance = 0f;
            lastX = ev.getX();
            lastY = ev.getY();
            break;
        case MotionEvent.ACTION_MOVE:
            final float curX = ev.getX();
            final float curY = ev.getY();
            xDistance += Math.abs(curX - lastX);
            yDistance += Math.abs(curY - lastY);
            lastX = curX;
            lastY = curY;
            if(xDistance &gt; yDistance)
                return false;
    }

    return super.onInterceptTouchEvent(ev);
}
}  
</code></pre>

